import os
import time
import hmac
import hashlib
import unicodedata
import re
from pathlib import PurePosixPath

# Secure file access service with path-based authorization
_SECRET_KEY = os.environ.get('FILE_SERVICE_KEY', '') or os.urandom(32)
if isinstance(_SECRET_KEY, str):
    _SECRET_KEY = _SECRET_KEY.encode('utf-8')

# Maximum allowed age (in seconds) for a signed request before it is rejected.
_MAX_REQUEST_AGE = 300  # 5 minutes

# Access control list: user -> list of allowed path prefixes
_ACL = {
    'admin': ['/data/', '/config/', '/logs/'],
    'analyst': ['/data/reports/', '/data/exports/'],
    'viewer': ['/data/reports/public/'],
}

def _normalize_path(path_str):
    """Normalize path to prevent traversal and canonicalize Unicode."""
    # Step 1: Unicode NFC normalization for consistent comparison
    normalized = unicodedata.normalize('NFC', path_str)
    # Step 2: Resolve path traversal sequences
    resolved = PurePosixPath('/' + normalized.lstrip('/')).as_posix()
    # Step 3: Collapse multiple slashes
    resolved = re.sub(r'/+', '/', resolved)
    # Step 4: Ensure trailing slash consistency for directories
    if not resolved.endswith('/'):
        resolved = resolved + '/'
    return resolved

def _is_timestamp_fresh(timestamp):
    """Reject stale or future timestamps to prevent replay attacks."""
    try:
        ts = float(timestamp)
    except (TypeError, ValueError):
        return False
    now = time.time()
    # Reject requests that are too old or too far in the future.
    return abs(now - ts) <= _MAX_REQUEST_AGE

def _verify_request_signature(user, path, timestamp, signature):
    """Verify HMAC signature of the request."""
    msg = f"{user}:{path}:{timestamp}".encode('utf-8')
    expected = hmac.new(_SECRET_KEY, msg, hashlib.sha256).digest()
    if not isinstance(signature, (bytes, bytearray)):
        return False
    return hmac.compare_digest(expected, signature)

def _check_authorization(user, requested_path):
    """Check if user is authorized to access the requested path."""
    if user not in _ACL:
        return False

    allowed_prefixes = _ACL[user]
    # Normalize the requested path for comparison
    norm_requested = _normalize_path(requested_path)

    for prefix in allowed_prefixes:
        norm_prefix = _normalize_path(prefix)
        if norm_requested.startswith(norm_prefix):
            return True
    return False

def _sanitize_filename(filename):
    """Remove dangerous characters from filename."""
    # Allow alphanumeric, dots, hyphens, underscores, slashes
    sanitized = re.sub(r'[^a-zA-Z0-9._\-/]', '', filename)
    return sanitized

def read_file(user, path, timestamp, signature):
    """Main entry point: authenticate, authorize, then read file."""
    # Step 0: Reject stale/replayed requests before doing anything else
    if not _is_timestamp_fresh(timestamp):
        return {'error': 'Stale or invalid timestamp', 'status': 401}

    # Step 1: Verify request signature
    if not _verify_request_signature(user, path, timestamp, signature):
        return {'error': 'Invalid signature', 'status': 401}

    # Step 2: Normalize path ONCE and use for both authz and file access
    normalized_path = _normalize_path(path)

    # Step 3: Check authorization against normalized path
    if not _check_authorization(user, normalized_path):
        return {'error': 'Access denied', 'status': 403}

    # Step 4: Read the file using the SAME normalized path
    sanitized = _sanitize_filename(normalized_path)
    file_path = '/srv/files' + sanitized

    try:
        with open(file_path, 'r') as f:
            content = f.read()
        return {'content': content, 'status': 200}
    except FileNotFoundError:
        return {'error': 'File not found', 'status': 404}
    except PermissionError:
        return {'error': 'Permission denied', 'status': 403}

def list_directory(user, path, timestamp, signature):
    """List directory contents with authorization."""
    # Step 0: Reject stale/replayed requests before doing anything else
    if not _is_timestamp_fresh(timestamp):
        return {'error': 'Stale or invalid timestamp', 'status': 401}

    if not _verify_request_signature(user, path, timestamp, signature):
        return {'error': 'Invalid signature', 'status': 401}

    # Normalize ONCE and use consistently
    normalized_path = _normalize_path(path)

    if not _check_authorization(user, normalized_path):
        return {'error': 'Access denied', 'status': 403}

    # Use sanitized normalized path for directory listing
    sanitized = _sanitize_filename(normalized_path)
    dir_path = '/srv/files' + sanitized

    try:
        entries = os.listdir(dir_path)
        return {'entries': entries, 'status': 200}
    except FileNotFoundError:
        return {'error': 'Directory not found', 'status': 404}
    except PermissionError:
        return {'error': 'Permission denied', 'status': 403}
